NDING // Invite sent, not yet accepted\n  LEAD // Accepted invite, no membership yet\n  FROZEN // Paused by student (injury, holiday)\n  ARCHIVED\n}\n\nenum ClaimStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  CANCELLED\n  COMPLETED // Class happened; see attendedAt for check-in timestamp\n  NO_SHOW\n}\n\nenum BookedByRole {\n  STUDENT // self-service booking via /api/bookings\n  STAFF // added on the student's behalf via the dashboard roster\n}\n\nenum MembershipStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  CANCELLED\n  EXPIRED\n}\n\nenum LeadStatus {\n  NEW\n  INVITED // Staff sent a membership invite, not yet accepted\n  CONTACTED\n  TRIAL_BOOKED\n  CONVERTED // Became a SchoolMember\n  LOST\n}\n\nenum LeadSource {\n  WEBSITE\n  INSTAGRAM\n  FACEBOOK\n  WALK_IN\n  REFERRAL\n  PHONE\n  INVITE // Staff-initiated membership invite\n  SELF_REQUEST // Visitor requested to join via \"Join this school\"\n  OTHER\n}\n\nenum EventType {\n  SEMINAR\n  COMPETITION\n  OPEN_MAT\n  WORKSHOP\n  SOCIAL\n  CAMP\n  OTHER\n}\n\nenum TransactionType {\n  INCOME\n  EXPENSE\n}\n\nenum TransactionCategory {\n  MEMBERSHIP\n  CLASS_BOOKING\n  PRODUCT_SALE\n  SALARY\n  RENT\n  EQUIPMENT\n  MARKETING\n  OTHER\n}\n\nenum TransactionStatus {\n  PAID\n  PENDING\n  FAILED\n  REFUNDED\n  CANCELLED\n  // A payment the provider (Stripe/Revolut) already captured, but that we\n  // deliberately did NOT turn into an active membership — e.g. the\n  // SchoolMember was ARCHIVED between checkout and webhook delivery. Never\n  // counted as confirmed revenue; surfaces in the dashboard Transactions\n  // list for manual review (refund or reactivation). See recordFlaggedPayment\n  // in lib/services/transactions.ts.\n  FLAGGED\n}\n\n// Martial's own SaaS subscription status for a school (schools paying\n// Martial), mirrors Stripe's real Subscription.status values so webhook\n// handlers can map 1:1 without inventing intermediate states.\nenum SchoolSubscriptionStatus {\n  TRIALING\n  ACTIVE\n  INCOMPLETE\n  INCOMPLETE_EXPIRED\n  PAST_DUE\n  UNPAID\n  PAUSED\n  CANCELED\n  INACTIVE\n}\n\nenum StripeWebhookEventStatus {\n  PROCESSING\n  PROCESSED\n  FAILED\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// AFFILIATION\n// Martial arts organizations / associations that affiliate academies\n// First use case: Roger Gracie Association (~50 academies worldwide)\n// Can have a content platform (e.g. Roger Gracie TV)\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel Affiliation {\n  id          String  @id @default(cuid())\n  name        String // \"Roger Gracie Association\"\n  slug        String  @unique // \"roger-gracie\"\n  description String?\n  logoUrl     String?\n  website     String?\n  instagram   String?\n  country     String? // HQ country\n\n  // Optional link to content platform (e.g. Roger Gracie TV)\n  // Resolved via ContentPlatform.affiliationId — no FK here to avoid circular\n  // Access: affiliation.contentPlatforms\n\n  schools          School[]\n  contentPlatforms ContentPlatform[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"affiliations\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// CONTENT PLATFORM  (Roger Gracie TV, future: Checkmat TV, etc.)\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel ContentPlatform {\n  id            String      @id @default(cuid())\n  affiliationId String\n  affiliation   Affiliation @relation(fields: [affiliationId], references: [id], onDelete: Cascade)\n\n  name        String // \"Roger Gracie TV\"\n  slug        String  @unique // \"rg-tv\"\n  description String?\n  logoUrl     String?\n  bannerUrl   String?\n  isActive    Boolean @default(true)\n\n  series          ContentSeries[]\n  accesses        ContentAccess[]\n  membershipPlans MembershipPlan[] // Plans that